"""matplotlib.lines — Line2D stub."""

import sys as _sys

# Single shared no-op fallback for unknown Line2D methods. Same
# pattern as patches.py: log once per class+method-name, return None.
_lines_warned = set()

def _lines_getattr_fallback(self, name):
    if name.startswith('_'):
        raise AttributeError(name)
    key = f'{type(self).__name__}.{name}'
    if key not in _lines_warned:
        _lines_warned.add(key)
        try:
            _sys.__stderr__.write(
                f"[mpl-shim] lines.{key}() not implemented — returning None\n")
        except Exception:
            pass
    def _noop(*args, **kwargs): return None
    return _noop


class Line2D:
    """Stub Line2D for API compatibility."""

    __getattr__ = _lines_getattr_fallback

    lineStyles = {'-': 'solid', '--': 'dashed', '-.': 'dashdot', ':': 'dotted'}
    markers = {'o': 'circle', 's': 'square', '^': 'triangle_up', 'v': 'triangle_down',
               'D': 'diamond', 'x': 'x', '+': 'plus', '*': 'star'}
    fillStyles = ('full', 'left', 'right', 'bottom', 'top', 'none')
    drawStyles = ('default', 'steps-pre', 'steps-mid', 'steps-post', 'steps')

    def __init__(self, xdata, ydata, **kwargs):
        self._x = xdata
        self._y = ydata
        self._color = kwargs.get('color', kwargs.get('c', None))
        self._linewidth = kwargs.get('linewidth', kwargs.get('lw', 1.5))
        self._linestyle = kwargs.get('linestyle', kwargs.get('ls', '-'))
        self._marker = kwargs.get('marker', None)
        self._markersize = kwargs.get('markersize', kwargs.get('ms', 6.0))
        self._markeredgecolor = kwargs.get('markeredgecolor', kwargs.get('mec', None))
        self._markerfacecolor = kwargs.get('markerfacecolor', kwargs.get('mfc', None))
        self._markerfacecoloralt = kwargs.get('markerfacecoloralt', kwargs.get('mfcalt', None))
        self._markeredgewidth = kwargs.get('markeredgewidth', kwargs.get('mew', 1.0))
        self._markevery = kwargs.get('markevery', None)
        self._fillstyle = kwargs.get('fillstyle', 'full')
        self._drawstyle = kwargs.get('drawstyle', kwargs.get('ds', 'default'))
        self._label = kwargs.get('label', '')
        self._alpha = kwargs.get('alpha', None)
        self._antialiased = kwargs.get('antialiased', kwargs.get('aa', True))
        self._dash_capstyle = kwargs.get('dash_capstyle', 'butt')
        self._dash_joinstyle = kwargs.get('dash_joinstyle', 'miter')
        self._solid_capstyle = kwargs.get('solid_capstyle', 'projecting')
        self._solid_joinstyle = kwargs.get('solid_joinstyle', 'miter')
        self._dashes = kwargs.get('dashes', None)
        self._gapcolor = kwargs.get('gapcolor', None)
        self._pickradius = kwargs.get('pickradius', 5)
        self._picker = kwargs.get('picker', None)
        self._visible = True
        self._zorder = kwargs.get('zorder', 2)
        self._url = None
        self._gid = None
        self._snap = None
        self._in_layout = True
        self._rasterized = False
        self._animated = False
        self._transform = None
        self._clip_box = None
        self._clip_on = True
        self._clip_path = None
        self._path_effects = []
        self._sketch = None

    # Data
    def get_xdata(self, orig=True): return self._x
    def get_ydata(self, orig=True): return self._y
    def get_data(self):       return (self._x, self._y)
    def set_xdata(self, x):   self._x = x
    def set_ydata(self, y):   self._y = y
    def set_data(self, *args):
        if len(args) == 1: self._x, self._y = args[0]
        elif len(args) == 2: self._x, self._y = args
    def get_xydata(self):
        import numpy as _np
        try:
            return _np.column_stack([self._x, self._y])
        except Exception:
            return []
    # Color / style
    def get_color(self):       return self._color
    def set_color(self, c):    self._color = c
    def get_c(self):           return self._color
    def set_c(self, c):        self._color = c
    def get_linewidth(self):   return self._linewidth
    def set_linewidth(self, w): self._linewidth = w
    def get_lw(self):          return self._linewidth
    def set_lw(self, w):       self._linewidth = w
    def get_linestyle(self):   return self._linestyle
    def set_linestyle(self, s): self._linestyle = s
    def get_ls(self):          return self._linestyle
    def set_ls(self, s):       self._linestyle = s
    def get_dashes(self):      return self._dashes
    def set_dashes(self, d):   self._dashes = d
    def get_drawstyle(self):   return self._drawstyle
    def set_drawstyle(self, d): self._drawstyle = d
    def get_ds(self):          return self._drawstyle
    def set_ds(self, d):       self._drawstyle = d
    def get_gapcolor(self):    return self._gapcolor
    def set_gapcolor(self, c): self._gapcolor = c
    # Marker
    def get_marker(self):      return self._marker
    def set_marker(self, m):   self._marker = m
    def get_markersize(self):  return self._markersize
    def set_markersize(self, s): self._markersize = s
    def get_ms(self):          return self._markersize
    def set_ms(self, s):       self._markersize = s
    def get_markerfacecolor(self): return self._markerfacecolor
    def set_markerfacecolor(self, c): self._markerfacecolor = c
    def get_mfc(self):         return self._markerfacecolor
    def set_mfc(self, c):      self._markerfacecolor = c
    def get_markeredgecolor(self): return self._markeredgecolor
    def set_markeredgecolor(self, c): self._markeredgecolor = c
    def get_mec(self):         return self._markeredgecolor
    def set_mec(self, c):      self._markeredgecolor = c
    def get_markeredgewidth(self): return self._markeredgewidth
    def set_markeredgewidth(self, w): self._markeredgewidth = w
    def get_mew(self):         return self._markeredgewidth
    def set_mew(self, w):      self._markeredgewidth = w
    def get_markerfacecoloralt(self): return self._markerfacecoloralt
    def set_markerfacecoloralt(self, c): self._markerfacecoloralt = c
    def get_mfcalt(self):      return self._markerfacecoloralt
    def set_mfcalt(self, c):   self._markerfacecoloralt = c
    def get_markevery(self):   return self._markevery
    def set_markevery(self, e): self._markevery = e
    def get_fillstyle(self):   return self._fillstyle
    def set_fillstyle(self, s): self._fillstyle = s
    # Cap / join
    def get_dash_capstyle(self):    return self._dash_capstyle
    def set_dash_capstyle(self, s): self._dash_capstyle = s
    def get_dash_joinstyle(self):   return self._dash_joinstyle
    def set_dash_joinstyle(self, s): self._dash_joinstyle = s
    def get_solid_capstyle(self):    return self._solid_capstyle
    def set_solid_capstyle(self, s): self._solid_capstyle = s
    def get_solid_joinstyle(self):   return self._solid_joinstyle
    def set_solid_joinstyle(self, s): self._solid_joinstyle = s
    # Label
    def get_label(self):       return self._label
    def set_label(self, l):    self._label = l
    # Alpha / visibility
    def get_alpha(self):       return self._alpha
    def set_alpha(self, a):    self._alpha = a
    def get_visible(self):     return self._visible
    def set_visible(self, v):  self._visible = bool(v)
    def get_antialiased(self): return self._antialiased
    def set_antialiased(self, b): self._antialiased = bool(b)
    def get_aa(self):          return self._antialiased
    def set_aa(self, b):       self._antialiased = bool(b)
    # Z-order / picker / metadata
    def get_zorder(self):      return self._zorder
    def set_zorder(self, z):   self._zorder = z
    def get_pickradius(self):  return self._pickradius
    def set_pickradius(self, r): self._pickradius = r
    def get_picker(self):      return self._picker
    def set_picker(self, p):   self._picker = p
    def get_url(self):         return self._url
    def set_url(self, u):      self._url = u
    def get_gid(self):         return self._gid
    def set_gid(self, g):      self._gid = g
    def get_snap(self):        return self._snap
    def set_snap(self, s):     self._snap = s
    def get_in_layout(self):   return self._in_layout
    def set_in_layout(self, b): self._in_layout = bool(b)
    def get_rasterized(self):  return self._rasterized
    def set_rasterized(self, b): self._rasterized = bool(b)
    def get_animated(self):    return self._animated
    def set_animated(self, b): self._animated = bool(b)
    def get_transform(self):   return self._transform
    def set_transform(self, t): self._transform = t
    def get_clip_box(self):    return self._clip_box
    def set_clip_box(self, b): self._clip_box = b
    def get_clip_on(self):     return self._clip_on
    def set_clip_on(self, b):  self._clip_on = bool(b)
    def get_clip_path(self):   return self._clip_path
    def set_clip_path(self, p): self._clip_path = p
    def get_path_effects(self): return list(self._path_effects)
    def set_path_effects(self, pe): self._path_effects = list(pe) if pe else []
    def get_sketch_params(self): return self._sketch
    def set_sketch_params(self, *a): self._sketch = a
    # Other
    def remove(self):          pass
    def draw(self, renderer):  pass
    def get_window_extent(self, renderer=None): return None
    def contains(self, ev):
        """Hit-test the line segments against an event x/y. Uses the
        line's ``pickradius`` (in data units, since the shim has no
        renderer to translate pixels). Returns ``(contains, info)``
        matching upstream's signature."""
        try:
            import numpy as _np
            x = _np.asarray(self._x, dtype=float).ravel()
            y = _np.asarray(self._y, dtype=float).ravel()
            ex = float(getattr(ev, 'xdata', ev[0] if hasattr(ev, '__len__') else None))
            ey = float(getattr(ev, 'ydata', ev[1] if hasattr(ev, '__len__') else None))
        except Exception:
            return False, {}
        if len(x) == 0 or ex is None or ey is None:
            return False, {}
        r = self._pickradius
        # Distance from event to each vertex.
        d = _np.hypot(x - ex, y - ey)
        ind = _np.where(d <= r)[0]
        if len(ind):
            return True, {'ind': ind.tolist()}
        return False, {}
    def update_from(self, other):
        for attr in ('color', 'linewidth', 'linestyle', 'marker',
                     'markersize', 'markerfacecolor', 'markeredgecolor',
                     'alpha', 'label', 'zorder', 'visible'):
            getter = getattr(other, f'get_{attr}', None)
            setter = getattr(self, f'set_{attr}', None)
            if getter and setter:
                try: setter(getter())
                except Exception: pass
    def update(self, props):
        for k, v in (props or {}).items():
            setter = getattr(self, f'set_{k}', None)
            if setter is not None:
                try: setter(v)
                except Exception: pass
    def findobj(self, match=None, include_self=True):
        return [self] if include_self else []
    def is_dashed(self):
        return self._linestyle in ('--', '-.', ':')
    def get_path(self):
        return None
    def get_window_extent(self, renderer=None):
        return None


