import numpy as _np


# Per-segment cap and join style enums — string sets, not real enums,
# matching the strings users pass to set_solid_capstyle etc.
_CAPSTYLES = ('butt', 'projecting', 'round')
_JOINSTYLES = ('miter', 'round', 'bevel')


class VertexSelector:
    """Lightweight stand-in for upstream's ``VertexSelector``. Tracks an
    optional list of ``(x, y)`` vertices that have been clicked on a
    line, so callers can subscribe to the line's pick events.
    """

    def __init__(self, line):
        self.line = line
        self.ind = []

    def process_selected(self, ind, xs, ys):
        # Default no-op; subclasses override to react to the selection.
        self.ind = list(ind)


class AxLine(Line2D):
    """A line specified by two points (``xy1`` and ``xy2``) or by a
    point and a slope. Renders as an extended line spanning the axes,
    matching :func:`axes.Axes.axline`."""

    def __init__(self, xy1, xy2=None, *, slope=None, **kwargs):
        x1, y1 = xy1
        if xy2 is None and slope is not None:
            # Pick a far-away second point in the slope direction.
            x2 = x1 + 1
            y2 = y1 + slope
        elif xy2 is not None:
            x2, y2 = xy2
        else:
            raise ValueError("AxLine requires either xy2 or slope")
        super().__init__([x1, x2], [y1, y2], **kwargs)
        self._xy1 = xy1
        self._xy2 = xy2
        self._slope = slope

    def get_xy1(self):    return self._xy1
    def get_xy2(self):    return self._xy2
    def get_slope(self):  return self._slope


def segment_hits(cx, cy, x, y, radius):
    """Return indices of line segments in ``(x, y)`` whose closest point
    to ``(cx, cy)`` is within ``radius``. Used by Line2D pick events.

    Computes the perpendicular distance from each segment to ``(cx, cy)``;
    cheap analytic formula (no per-point iteration).
    """
    x = _np.asarray(x, dtype=float)
    y = _np.asarray(y, dtype=float)
    if len(x) < 2:
        return _np.array([], dtype=int)
    xr = x[1:] - x[:-1]
    yr = y[1:] - y[:-1]
    # Distance from a point to each segment, clamped to the segment.
    dx = cx - x[:-1]
    dy = cy - y[:-1]
    length_sq = xr ** 2 + yr ** 2
    # t is the projection along each segment; clip to [0, 1].
    t = _np.where(length_sq > 0, (dx * xr + dy * yr) / length_sq, 0.0)
    t = _np.clip(t, 0.0, 1.0)
    # Closest point on each segment.
    px = x[:-1] + t * xr
    py = y[:-1] + t * yr
    dist_sq = (cx - px) ** 2 + (cy - py) ** 2
    return _np.where(dist_sq <= radius ** 2)[0]


def _slice_or_none(c, s):
    """Helper used by some upstream code paths — slice ``c`` by ``s``
    if it's array-like, otherwise return ``c`` as-is."""
    if c is None or _np.isscalar(c):
        return c
    return _np.asarray(c)[s]


# Marker functions on Line2D itself — provide get_*/set_* accessors so
# matplotlib snippets that reach for cap/join styles don't AttributeError.
def _attach_cap_join_accessors(cls):
    def _set_solid_capstyle(self, s):       self._scap = s
    def _get_solid_capstyle(self):          return getattr(self, '_scap', 'butt')
    def _set_dash_capstyle(self, s):        self._dcap = s
    def _get_dash_capstyle(self):           return getattr(self, '_dcap', 'butt')
    def _set_solid_joinstyle(self, s):      self._sjoin = s
    def _get_solid_joinstyle(self):         return getattr(self, '_sjoin', 'round')
    def _set_dash_joinstyle(self, s):       self._djoin = s
    def _get_dash_joinstyle(self):          return getattr(self, '_djoin', 'round')
    cls.set_solid_capstyle = _set_solid_capstyle
    cls.get_solid_capstyle = _get_solid_capstyle
    cls.set_dash_capstyle = _set_dash_capstyle
    cls.get_dash_capstyle = _get_dash_capstyle
    cls.set_solid_joinstyle = _set_solid_joinstyle
    cls.get_solid_joinstyle = _get_solid_joinstyle
    cls.set_dash_joinstyle = _set_dash_joinstyle
    cls.get_dash_joinstyle = _get_dash_joinstyle
_attach_cap_join_accessors(Line2D)


