def _attach_line2d_methods(cls):
    """Fill in the remaining :class:`Line2D` getters/setters that real
    matplotlib exposes."""

    def contains(self, mouseevent):
        return False, {}

    def draw(self, renderer): pass

    def get_data(self, orig=True):
        return (list(self._x) if hasattr(self._x, '__iter__') else self._x,
                list(self._y) if hasattr(self._y, '__iter__') else self._y)

    def get_drawstyle(self):           return getattr(self, '_drawstyle', 'default')
    def set_drawstyle(self, ds):       self._drawstyle = ds

    def get_fillstyle(self):           return getattr(self, '_fillstyle', 'full')
    def set_fillstyle(self, fs):       self._fillstyle = fs

    def get_antialiased(self):         return getattr(self, '_aa', True)
    def set_antialiased(self, b):      self._aa = bool(b)

    def get_bbox(self):
        import numpy as _np
        xs = _np.asarray(self._x); ys = _np.asarray(self._y)
        if xs.size == 0 or ys.size == 0:
            return _np.array([0.0, 0.0, 1.0, 1.0])
        return _np.array([xs.min(), ys.min(), xs.max(), ys.max()])

    def get_gapcolor(self):            return getattr(self, '_gapcolor', None)
    def set_gapcolor(self, c):         self._gapcolor = c

    def get_markeredgecolor(self):     return getattr(self, '_mec', None) or self._color
    def set_markeredgecolor(self, c):  self._mec = c
    def get_markeredgewidth(self):     return getattr(self, '_mew', 1.0)
    def set_markeredgewidth(self, w):  self._mew = float(w)
    def get_markerfacecolor(self):     return getattr(self, '_mfc', None) or self._color
    def set_markerfacecolor(self, c):  self._mfc = c
    def get_markerfacecoloralt(self):  return getattr(self, '_mfca', 'none')
    def set_markerfacecoloralt(self, c):self._mfca = c
    def get_markersize(self):          return getattr(self, '_ms', 6)
    def set_markersize(self, s):       self._ms = float(s)
    def get_markevery(self):           return getattr(self, '_markevery', None)
    def set_markevery(self, e):        self._markevery = e

    def get_path(self):
        from matplotlib.path import Path
        import numpy as _np
        return Path(_np.column_stack([self._x, self._y])
                    if hasattr(self._x, '__iter__') else [[self._x, self._y]])

    def get_pickradius(self):          return getattr(self, '_pickradius', 5)
    def set_pickradius(self, r):       self._pickradius = float(r)

    def get_solid_capstyle(self):      return getattr(self, '_scap', 'butt')
    def get_solid_joinstyle(self):     return getattr(self, '_sjoin', 'round')
    def get_dash_capstyle(self):       return getattr(self, '_dcap', 'butt')
    def get_dash_joinstyle(self):      return getattr(self, '_djoin', 'round')
    def get_path_effects(self):        return getattr(self, '_pe', [])
    def set_path_effects(self, pe):    self._pe = pe

    def get_window_extent(self, renderer=None): return self.get_bbox()
    def get_xydata(self):
        import numpy as _np
        return _np.column_stack([self._x, self._y]) if hasattr(self._x, '__iter__') else _np.array([[self._x, self._y]])

    def is_dashed(self):
        return self._linestyle in ('--', '-.', ':', 'dashed', 'dashdot', 'dotted')

    def update(self, props):
        if isinstance(props, dict):
            for k, v in props.items():
                setter = getattr(self, f'set_{k}', None)
                if setter: setter(v)

    def update_from(self, other):
        for attr in ('color', 'linestyle', 'linewidth', 'marker', 'alpha'):
            getter = getattr(other, f'get_{attr}', None)
            setter = getattr(self, f'set_{attr}', None)
            if getter and setter:
                try: setter(getter())
                except Exception: pass

    def set_dashes(self, seq):         self._dashes = seq
    def get_dashes(self):              return getattr(self, '_dashes', None)

    def set_pickle_compat(self, *a):   pass

    def set_data(self, *args):
        if len(args) == 1:
            self._x, self._y = args[0]
        else:
            self._x, self._y = args[0], args[1]
    def set_xdata(self, x): self._x = x
    def set_ydata(self, y): self._y = y

    def get_xdata(self, orig=True): return self._x
    def get_ydata(self, orig=True): return self._y

    def pickable(self):                return self._picker is not None
    def set_picker(self, picker):      self._picker = picker
    def get_picker(self):              return getattr(self, '_picker', None)

    def remove(self): pass

    _l = locals()
    for name in ('contains', 'draw', 'get_data', 'get_drawstyle', 'set_drawstyle',
                  'get_fillstyle', 'set_fillstyle', 'get_antialiased',
                  'set_antialiased', 'get_bbox', 'get_gapcolor', 'set_gapcolor',
                  'get_markeredgecolor', 'set_markeredgecolor',
                  'get_markeredgewidth', 'set_markeredgewidth',
                  'get_markerfacecolor', 'set_markerfacecolor',
                  'get_markerfacecoloralt', 'set_markerfacecoloralt',
                  'get_markersize', 'set_markersize',
                  'get_markevery', 'set_markevery',
                  'get_path', 'get_pickradius', 'set_pickradius',
                  'get_solid_capstyle', 'get_solid_joinstyle',
                  'get_dash_capstyle', 'get_dash_joinstyle',
                  'get_path_effects', 'set_path_effects',
                  'get_window_extent', 'get_xydata',
                  'is_dashed', 'update', 'update_from',
                  'set_dashes', 'get_dashes', 'set_pickle_compat',
                  'set_data', 'set_xdata', 'set_ydata',
                  'get_xdata', 'get_ydata',
                  'pickable', 'set_picker', 'get_picker', 'remove'):
        if name in _l:
            setattr(cls, name, _l[name])

_attach_line2d_methods(Line2D)


